// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.agenticimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.common.Resultimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Agentic planner. * * The planner decides what action to take next, given: *   - The original user input *   - The available tools (with descriptions) *   - The history of previous steps (thoughts + actions + observations) * * ## ReAct Pattern * * The planner implements the Reason+Act loop: * * ``` * Step 1: Thought("User wants to know the weather. I should call weather_tool.") *         Action(ToolCall("weather_tool", {"location": "Bangalore"})) *         Observation(ToolSuccess(output="28°C, sunny")) * * Step 2: Thought("I have the weather. I can now answer the user.") *         Action(FinalAnswer("It's 28°C and sunny in Bangalore.")) * ``` * * ## Implementation * * The default [LlmAgenticPlanner] uses an LLM (local or cloud) to generate * the next thought + action. The LLM is prompted with: *   - The user's original question *   - The tool catalog (id + description + param schema) *   - The conversation history (previous thoughts + actions + observations) *   - A system prompt explaining the ReAct format * * The LLM responds with a structured JSON: * ```json * { *   "thought": "I need to search the web for the latest news.", *   "action": { *     "type": "tool_call", *     "toolId": "search_web", *     "params": {"query": "latest AI news"} *   } * } * ``` * * The planner parses this JSON and returns a [PlannerDecision]. * * ## Privacy * *   - Tool descriptions and param schemas are sent to the LLM (needed for *     the LLM to know how to use the tools). *   - Previous observations may contain user data — they're sent to the LLM *     only if the LLM is local (cloud LLM gets scrubbed observations). * * @see <a href="docs/spec/module2-spec-review.pdf">§9.1 Planner</a> */interface AgenticPlanner {    /**     * Decide the next action to take.     *     * @param userInput the original user input     * @param toolCatalog list of available tools (with descriptions)     * @param previousSteps the workflow's previous steps (for context)     * @param context the brain context     * @return [PlannerDecision] with the next thought + action     */    suspend fun planNext(        userInput: String,        toolCatalog: List<AgenticTool>,        previousSteps: List<WorkflowStep>,        context: BrainContext,    ): Result<PlannerDecision>}/** * A planner's decision — the next thought + action to take. */data class PlannerDecision(    /** LLM's reasoning for why it chose this action. */    val thought: String,    /** The action to take (tool call, LLM query, or final answer). */    val action: AgenticStep,) {    init {        require(thought.isNotBlank()) { "Thought cannot be blank" }    }}/** * NOUS — LLM-based agentic planner (default implementation). * * Uses an LLM (local or cloud) to generate the next thought + action. * * Real LLM integration ships in Module 4 (:feature:llm). For Module 2, * this is an interface — tests use `FakeAgenticPlanner` (in `src/test/kotlin/`) * to inject predetermined decisions. * * ## Prompt Structure * * The planner builds a prompt like: * * ``` * You are NOUS, an AI assistant using the ReAct pattern. * * User's question: {{user_input}} * * Available tools: *   - search_web: Search the web. Params: query (required) *   - fetch_url: Fetch a URL. Params: url (required) *   - recall_memory: Recall a memory. Params: query (required) * * Previous steps: *   Step 1: Thought("I should search the web.") *           Action(ToolCall("search_web", {"query": "AI news"})) *           Observation("Found 5 results about AI news") * * What should I do next? Respond in JSON: * {"thought": "...", "action": {"type": "tool_call", "toolId": "...", "params": {...}}} * ``` * * The LLM's response is parsed into a [PlannerDecision]. * * ## Fallback * * If the LLM response can't be parsed (malformed JSON), the planner returns * [Result.Failure] and the orchestrator stops the workflow with FAILED status. */@Singletonclass LlmAgenticPlanner(    private val llmCaller: suspend (String, BrainContext) -> Result<String>,) : AgenticPlanner {    override suspend fun planNext(        userInput: String,        toolCatalog: List<AgenticTool>,        previousSteps: List<WorkflowStep>,        context: BrainContext,    ): Result<PlannerDecision> {        val prompt = buildPrompt(userInput, toolCatalog, previousSteps)        val llmResult = llmCaller(prompt, context)        return when (llmResult) {            is Result.Failure -> llmResult            is Result.Success -> {                val response = llmResult.data                parseDecision(response)            }            is Result.Partial -> {                val response = llmResult.data                parseDecision(response)            }        }    }    /**     * Build the prompt for the LLM.     */    private fun buildPrompt(        userInput: String,        toolCatalog: List<AgenticTool>,        previousSteps: List<WorkflowStep>,    ): String {        val toolsSection = if (toolCatalog.isEmpty()) {            "(no tools available — use llm_query or final_answer)"        } else {            toolCatalog.joinToString("\n") { tool ->                val params = if (tool.paramSchema.isEmpty()) {                    "(no params)"                } else {                    tool.paramSchema.joinToString(", ") { param ->                        "${param.name}${if (param.required) " (required)" else ""}"                    }                }                "  - ${tool.id}: ${tool.description} Params: $params"            }        }        val historySection = if (previousSteps.isEmpty()) {            "(no previous steps)"        } else {            previousSteps.joinToString("\n") { step ->                val actionDesc = when (step.action) {                    is AgenticStep.ToolCall -> {                        "ToolCall(\"${step.action.toolId}\", ${step.action.params})"                    }                    is AgenticStep.LlmQuery -> "LlmQuery(\"${step.action.prompt.take(80)}...\")"                    is AgenticStep.FinalAnswer -> "FinalAnswer(\"${step.action.answer.take(80)}...\")"                }                val obsDesc = when (step.observation) {                    is AgenticStepResult.ToolSuccess -> "Observation(\"${step.observation.output.take(100)}\")"                    is AgenticStepResult.ToolFailure -> "Observation(Error: ${step.observation.error.take(80)})}"                    is AgenticStepResult.LlmSuccess -> "Observation(\"${step.observation.text.take(100)}\")"                    is AgenticStepResult.LlmFailure -> "Observation(Error: ${step.observation.error.take(80)})}"                    is AgenticStepResult.FinalAnswerProduced -> "FinalAnswer(\"${step.observation.answer.take(80)}\")"                    null -> "(no observation)"                }                "  Step ${step.stepNumber}: Thought(\"${step.thought ?: "(none)"}\")\n" +                    "          Action($actionDesc)\n" +                    "          $obsDesc"            }        }        return buildString {            appendLine("You are NOUS, an AI assistant using the ReAct (Reason + Act) pattern.")            appendLine()            appendLine("User's question: $userInput")            appendLine()            appendLine("Available tools:")            append(toolsSection)            appendLine()            appendLine()            appendLine("Available action types:")            appendLine("  - tool_call: invoke a tool with params")            appendLine("  - llm_query: ask yourself a follow-up question")            appendLine("  - final_answer: produce the final answer for the user")            appendLine()            appendLine("Previous steps:")            append(historySection)            appendLine()            appendLine()            appendLine("What should I do next? Respond in EITHER format:")            appendLine()            appendLine("Format 1 (JSON):")            appendLine("""{"thought": "your reasoning", "action": {"type": "tool_call"|"llm_query"|"final_answer", ...}}""")            appendLine()            appendLine("Format 2 (ReAct text):")            appendLine("Thought: your reasoning")            appendLine("Action: tool_id")            appendLine("""Action Input: {"param": "value"}""")            appendLine()            appendLine("Or for final answer:")            appendLine("Thought: your reasoning")            appendLine("Final Answer: your answer here")            appendLine()            appendLine("Examples (JSON):")            appendLine("""{"thought": "I need to search the web", "action": {"type": "tool_call", "toolId": "search_web", "params": {"query": "AI news"}}}""")            appendLine("""{"thought": "I have enough info to answer", "action": {"type": "final_answer", "answer": "The answer is..."}}""")            appendLine()            appendLine("Examples (ReAct):")            appendLine("Thought: I need to search the web")            appendLine("Action: search_web")            appendLine("""Action Input: {"query": "AI news"}""")            appendLine()            appendLine("Thought: I have enough info")            appendLine("Final Answer: The answer is 42.")        }    }    /**     * Parse the LLM's response into a [PlannerDecision].     *     * Tries 3 parsing strategies in order (defensive — small LLMs produce     * unpredictable output):     *     *   1. **JSON parsing** — extract JSON object, parse fields     *   2. **ReAct text parsing** — "Thought: ... Action: ..." format     *   3. **Fallback** — treat entire response as FinalAnswer     *     * This 3-tier approach ensures the agentic loop never hangs due to     * malformed LLM output.     */    private fun parseDecision(response: String): Result<PlannerDecision> {        val correlationId = com.roshan.persona.common.CorrelationId.generate()        // ─── Strategy 1: Try JSON parsing ─────────────────────────────        val jsonStr = extractJson(response)        if (jsonStr != null) {            try {                val decision = parseJson(jsonStr)                return Result.Success(decision, correlationId, 0)            } catch (e: Exception) {                Timber.tag("NOUS.L5").w("JSON parse failed, trying ReAct format: %s", e.message)                // Fall through to strategy 2            }        }        // ─── Strategy 2: Try ReAct text format ────────────────────────        val reactDecision = parseReActFormat(response)        if (reactDecision != null) {            Timber.tag("NOUS.L5").v("ReAct format parsed successfully")            return Result.Success(reactDecision, correlationId, 0)        }        // ─── Strategy 3: Fallback — treat as FinalAnswer ──────────────        // If LLM produced text but no parseable action, assume it's answering        val fallbackAnswer = response.trim()            .removePrefix("```").removeSuffix("```")            .removePrefix("Answer:").removePrefix("answer:")            .trim()        if (fallbackAnswer.isNotBlank()) {            Timber.tag("NOUS.L5").w("Using fallback FinalAnswer (no JSON or ReAct format)")            return Result.Success(                PlannerDecision(                    thought = "LLM response did not contain parseable action — treating as final answer",                    action = AgenticStep.FinalAnswer(answer = fallbackAnswer),                ),                correlationId,                0,            )        }        // ─── All strategies failed ────────────────────────────────────        return Result.Failure(            error = com.roshan.persona.common.AppError.Unknown(                cause = IllegalArgumentException("Could not parse LLM response: ${response.take(200)}"),                correlationId = correlationId,            ),            correlationId = correlationId,            durationNanos = 0,        )    }    /**     * Parse ReAct text format: "Thought: ... Action: ...".     *     * Common patterns small LLMs produce:     *   ```     *   Thought: I need to search the web     *   Action: search_web     *   Action Input: {"query": "AI news"}     *   ```     *     *   ```     *   Thought: I have enough info     *   Action: final_answer     *   Action Input: The answer is 42     *   ```     */    private fun parseReActFormat(response: String): PlannerDecision? {        // Extract Thought        val thoughtMatch = Regex(            """Thought\s*:\s*(.+?)(?=\n\s*(?:Action|Final Answer|$))""",            RegexOption.IGNORE_CASE,        ).find(response)        val thought = thoughtMatch?.groupValues?.getOrNull(1)?.trim()            ?: return null  // No Thought found — can't parse        // Try "Action: <tool_id>" + "Action Input: <params>"        val actionMatch = Regex(            """Action\s*:\s*(.+?)(?=\n\s*(?:Action Input|$))""",            RegexOption.IGNORE_CASE,        ).find(response)        val actionInputMatch = Regex(            """Action Input\s*:\s*(.+?)(?=\n\s*(?:Thought|Action|Final Answer|$))""",            RegexOption.IGNORE_CASE,        ).find(response)        if (actionMatch != null) {            val actionStr = actionMatch.groupValues[1].trim()            val actionInput = actionInputMatch?.groupValues?.getOrNull(1)?.trim() ?: ""            // Check if it's a final answer            if (actionStr.equals("final_answer", ignoreCase = true) ||                actionStr.equals("final answer", ignoreCase = true) ||                actionStr.equals("answer", ignoreCase = true)            ) {                return PlannerDecision(                    thought = thought,                    action = AgenticStep.FinalAnswer(answer = actionInput.ifBlank { thought }),                )            }            // Try to parse action input as JSON params            val params = if (actionInput.startsWith("{")) {                parseParamsFromJson(actionInput)            } else {                // Treat as single "input" param                if (actionInput.isNotBlank()) {                    mapOf("input" to actionInput)                } else {                    emptyMap()                }            }            return PlannerDecision(                thought = thought,                action = AgenticStep.ToolCall(toolId = actionStr, params = params),            )        }        // Try "Final Answer: ..."        val finalAnswerMatch = Regex(            """Final Answer\s*:\s*(.+)""",            RegexOption.IGNORE_CASE,        ).find(response)        if (finalAnswerMatch != null) {            val answer = finalAnswerMatch.groupValues[1].trim()            return PlannerDecision(                thought = thought,                action = AgenticStep.FinalAnswer(answer = answer),            )        }        return null    }    /**     * Parse params from a JSON string (used by ReAct format parser).     */    private fun parseParamsFromJson(jsonStr: String): Map<String, String> {        return try {            val paramPattern = Regex(""""(\w+)"\s*:\s*"((?:[^"\\]|\\.)*)"""")            paramPattern.findAll(jsonStr)                .associate { match ->                    match.groupValues[1] to match.groupValues[2].unescapeJson()                }        } catch (e: Exception) {            emptyMap()        }    }    /**     * Extract JSON object from response. Handles:     *   - Plain JSON: {"thought": "...", "action": {...}}     *   - Markdown-wrapped: ```json {...} ```     *   - JSON with text before/after: "Here's my response: {...} hope it helps"     */    private fun extractJson(response: String): String? {        // Try markdown-wrapped first        val markdownMatch = Regex("""```(?:json)?\s*(\{[\s\S]*?\})\s*```""").find(response)        if (markdownMatch != null) return markdownMatch.groupValues[1]        // Try plain JSON (first { to last })        val firstBrace = response.indexOf('{')        val lastBrace = response.lastIndexOf('}')        if (firstBrace >= 0 && lastBrace > firstBrace) {            return response.substring(firstBrace, lastBrace + 1)        }        return null    }    /**     * Parse JSON into PlannerDecision. Manual parsing (no JSON library in Module 2).     */    private fun parseJson(json: String): PlannerDecision {        // Extract thought        val thoughtMatch = Regex(""""thought"\s*:\s*"((?:[^"\\]|\\.)*)"""").find(json)        val thought = thoughtMatch?.groupValues?.getOrNull(1)?.unescapeJson()            ?: throw IllegalArgumentException("Missing 'thought' field")        // Extract action type        val typeMatch = Regex(""""type"\s*:\s*"(\w+)"""").find(json)        val actionType = typeMatch?.groupValues?.getOrNull(1)            ?: throw IllegalArgumentException("Missing 'action.type' field")        val action: AgenticStep = when (actionType) {            "tool_call" -> {                val toolIdMatch = Regex(""""toolId"\s*:\s*"([^"]+)"""").find(json)                val toolId = toolIdMatch?.groupValues?.getOrNull(1)                    ?: throw IllegalArgumentException("Missing 'toolId' for tool_call")                val params = extractParams(json)                AgenticStep.ToolCall(toolId = toolId, params = params)            }            "llm_query" -> {                val promptMatch = Regex(""""prompt"\s*:\s*"((?:[^"\\]|\\.)*)"""").find(json)                val prompt = promptMatch?.groupValues?.getOrNull(1)?.unescapeJson()                    ?: throw IllegalArgumentException("Missing 'prompt' for llm_query")                AgenticStep.LlmQuery(prompt = prompt)            }            "final_answer" -> {                val answerMatch = Regex(""""answer"\s*:\s*"((?:[^"\\]|\\.)*)"""").find(json)                val answer = answerMatch?.groupValues?.getOrNull(1)?.unescapeJson()                    ?: throw IllegalArgumentException("Missing 'answer' for final_answer")                AgenticStep.FinalAnswer(answer = answer)            }            else -> throw IllegalArgumentException("Unknown action type: $actionType")        }        return PlannerDecision(thought = thought, action = action)    }    /**     * Extract params map from JSON (for tool_call actions).     */    private fun extractParams(json: String): Map<String, String> {        val paramsMatch = Regex(""""params"\s*:\s*\{([^}]*)\}""").find(json)            ?: return emptyMap()        val paramsStr = paramsMatch.groupValues[1]        val paramPattern = Regex(""""(\w+)"\s*:\s*"((?:[^"\\]|\\.)*)"""")        return paramPattern.findAll(paramsStr)            .associate { match ->                match.groupValues[1] to match.groupValues[2].unescapeJson()            }    }    /**     * Unescape JSON string escapes (\n, \", \\, etc.).     */    private fun String.unescapeJson(): String {        return this            .replace("\\n", "\n")            .replace("\\\"", "\"")            .replace("\\\\", "\\")            .replace("\\t", "\t")    }}
